class Permissions:
    def allowed(self, role, action):
        if role == 'viewer':
            return action =='read'
        elif role == 'editor':
            return action in ['read', 'write']
        return False

    def roles_for(self, action):
        roles = []
        for role in ['viewer', 'editor']:
            if self.allowed(role, action):
                roles.append(role)
        return sorted(roles)
